// Load line.json (the simulator's plant definition) and hand it to the
// line engine. Runs once at start; send any message to load it again.
// Input: any message. Output: msg.topic "config", msg.payload = the line.
const fs = global.get("fs");
const file = env.get("OFM_LINESIM_CONFIG") || "/demo/line.json";
let line;
try {
    line = JSON.parse(fs.readFileSync(file, "utf8"));
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: "cannot read " + file });
    node.error("cannot read " + file + ": " + e.message);
    return null;
}

// Basic checks, so a typing error in line.json is reported clearly instead
// of producing a strange line.
const problems = [];
const machines = (line.machines || []).filter(m => m.enabled !== false);
if (machines.length < 2 || machines.length > 10) problems.push("2 to 10 enabled machines needed");
const slots = new Set();
for (const m of machines) {
    if (!Number.isInteger(m.slot) || m.slot < 1 || m.slot > 10) problems.push(m.name + ": slot must be 1 to 10");
    if (slots.has(m.slot)) problems.push("slot " + m.slot + " used twice");
    slots.add(m.slot);
    if (!/^[a-z][a-z0-9_]*$/.test(m.name || "")) problems.push("machine name '" + m.name + "': lowercase a-z, 0-9, _");
    if (!(m.ratedPerMin > 0)) problems.push(m.name + ": ratedPerMin must be above 0");
    if (!(m.inPerUnit >= 0)) problems.push(m.name + ": inPerUnit must be 0 or more");
}
machines.sort((a, b) => a.slot - b.slot).forEach((m, i) => {
    if (i < machines.length - 1 && !(m.bufferAfter >= 1)) problems.push(m.name + ": bufferAfter must be 1 or more");
    if (i === 0 && m.inPerUnit !== 0) problems.push(m.name + ": the first machine has an unlimited supply: inPerUnit must be 0");
    if (i > 0 && !(m.inPerUnit >= 1)) problems.push(m.name + ": inPerUnit must be 1 or more (only the first machine has an unlimited supply)");
});
if (machines.filter(m => m.constraint).length !== 1) problems.push("exactly one machine must be the constraint");
if (!(line.products || []).some(p => p.sku === line.freeRunSku)) problems.push("freeRunSku is not one of the products");
if (problems.length) {
    node.status({ fill: "red", shape: "ring", text: problems.length + " problem(s) in line.json" });
    node.error("line.json: " + problems.join("; "));
    return null;
}
node.status({ fill: "green", shape: "dot", text: machines.length + " machines, loaded " + new Date().toLocaleTimeString() });
return { topic: "config", payload: line };

// Line engine (ADR-0023): moves the simulated packing line forward on every
// tick and reports each machine's interface (demo/packing-line/README.md,
// section 4).
//
// Inputs (msg.topic):
//   "config" - the line from line.json: (re)build the line; counters of
//              machines that stay in the same slot are kept, and so are the
//              product, a running changeover and a stopped line
//   "tick"   - every 100 ms; msg.now (epoch ms) may replace the clock (tests)
//   "cmd"    - a command from the control panel, msg.payload.cmd:
//              break {slot, code?, minutes?, hold?} · jam {slot, seconds?} ·
//              repair {slot} · stop · run · pause · resume ·
//              product {sku, minutes?, changeover?} · schedule {enabled} ·
//              set {slot?, key, value} · preset {name} · newrun ·
//              follow {enabled} · auto {enabled} · startorder {sku, qty} ·
//              completeorder
//   ".../workorder" - OFM's active work order (MQTT, retained; step 3a.5):
//              while "follow" is on, the line makes only what an active
//              order asks for: a new product means a changeover; the line
//              stops at the order's planned quantity of good units at the
//              output machine, and waits while there is no active order
//   "orderresult" - the answer of the database to a start or complete
// Output 1 (to the simulated PLCs): on every tick, msg.payload = the line's
//   snapshot (ts, mode, sku, heartbeat, machines[] with the nine interface
//   signals and the conveyor after each machine). Nothing is sent while
//   paused: values freeze and the heartbeat stops, as when a PLC program
//   stops (ADR-0025).
// Output 2 (to the control panel): once a second, also while paused, the
//   snapshot plus what the panel shows: settings, products, presets, this
//   hour's output against rated, the order.
// Output 3 (to "work orders"): start {sku, qty, by} or complete {by}, from
//   the panel or from the auto-operator, which starts the next order of the
//   plan in line.json (orders.autoOperator) when the line has no order or
//   has finished it, inside the shift pattern, after delayMin minutes.
const STATE = { running: 1, idle: 2, blocked: 3, starved: 4, fault: 5, setup: 6, cleaning: 7, maintenance: 8 };
const MODE_STATE = { off: STATE.idle, cleaning: STATE.cleaning, setup: STATE.setup, waiting: STATE.idle };
const MACHINE_KEYS = ["speedPct", "mtbfH", "mttrMin", "jamsPerH", "rejectPct"];   // what "set" may change
const LINE_KEYS = ["unknownFaultPct", "debounceS"];

let sim = context.get("sim");
const now = Number.isFinite(msg.now) ? msg.now : Date.now();

// --- random numbers: seeded, so a test (or a demo) can be repeated -----------------
function rand() {                      // mulberry32: small, fast, good enough for a simulation
    let t = (sim.rngState = (sim.rngState + 0x6D2B79F5) | 0);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const uniform = (a, b) => a + (b - a) * rand();
const normal = () => Math.sqrt(-2 * Math.log(rand() || 1e-12)) * Math.cos(2 * Math.PI * rand());
const pick = list => list[Math.floor(rand() * list.length)];
const round1 = x => Math.round(x * 10) / 10;

// --- the shift pattern, in the line's local time -------------------------------------
const toMinutes = hm => { const [h, m] = String(hm).split(":").map(Number); return h * 60 + m; };
function scheduleMode(ts) {
    const s = sim.line.schedule || {};
    if (!s.enabled) return "run";
    const minuteKey = Math.floor(ts / 60000);
    if (sim.scheduleCache.minute === minuteKey) return sim.scheduleCache.mode;
    const parts = new Intl.DateTimeFormat("en-AU", {
        timeZone: s.timeZone || "Australia/Melbourne", weekday: "short", hour: "2-digit", minute: "2-digit", hourCycle: "h23"
    }).formatToParts(new Date(ts));
    const get = type => (parts.find(p => p.type === type) || {}).value;
    const day = get("weekday"), minute = Number(get("hour")) * 60 + Number(get("minute"));
    let mode = "off";
    if ((s.days || []).includes(day)) {
        if (s.cleaning && minute >= toMinutes(s.cleaning.start) && minute < toMinutes(s.cleaning.end)) mode = "cleaning";
        else if (minute >= toMinutes(s.start) && minute < toMinutes(s.end)) mode = "run";
    }
    sim.scheduleCache = { minute: minuteKey, mode };
    return mode;
}

// --- building the line -----------------------------------------------------------------
function build(line, old) {
    const kept = {};
    for (const m of (old ? old.machines : [])) kept[m.cfg.slot] = m;
    const machines = line.machines.filter(c => c.enabled !== false).sort((a, b) => a.slot - b.slot).map(c => {
        const k = kept[c.slot] || {};
        return {
            cfg: JSON.parse(JSON.stringify(c)), state: STATE.idle, fault: null, acc: 0,
            waiting: null, lastOutAt: now, lastTakenAt: now, speedEma: 0, setpoint: 0,
            count_in: k.count_in || 0, count_good: k.count_good || 0, count_reject: k.count_reject || 0,
            process_value: k.process_value || 0, buffer: 0, casesOnPallet: k.casesOnPallet || 0, pallets: k.pallets || 0
        };
    });
    return {
        line: JSON.parse(JSON.stringify(line)), machines, last: now,
        heartbeat: old ? old.heartbeat : 0, lastSecond: Math.floor(now / 1000),
        rngState: (line.seed ? line.seed : Math.floor(Math.random() * 2147483647)) | 0,
        mode: "off", stopped: old ? old.stopped : false, paused: false,
        sku: old && line.products.some(p => p.sku === old.sku) ? old.sku : line.freeRunSku,
        changeoverUntil: old ? old.changeoverUntil : 0,
        scheduleCache: { minute: -1, mode: null },
        base: JSON.parse(JSON.stringify(line)), preset: "line", lastPanel: 0,
        hour: null, lastHour: null,
        // Work orders (step 3a.5): OFM's active order as last received, and
        // the output machine's good count when this simulator first saw it.
        order: old ? old.order : { active: false },
        follow: old ? old.follow : !(line.orders && line.orders.follow === false),
        auto: old ? old.auto : { enabled: !!(line.orders && line.orders.autoOperator && line.orders.autoOperator.enabled),
                                 next: 0, waitingSince: null, pending: null, lastError: null }
    };
}

// The machine whose good count is the line's output (line.json lineOutput;
// the constraint if not given).
const outputMachine = () => sim.machines.find(x => x.cfg.name === sim.line.lineOutput) || sim.machines.find(x => x.cfg.constraint);

// This hour's line output against what the line could have made at rated
// speed in the time it was scheduled to run (changeovers, cleaning and
// time off do not count) - the simulator's own rough figure for the panel.
function trackHour(dt) {
    const hourStart = Math.floor(now / 3600000) * 3600000;
    const out = outputMachine();
    if (!sim.hour || sim.hour.start !== hourStart) {
        if (sim.hour) sim.lastHour = hourSummary();
        sim.hour = { start: hourStart, good0: out.count_good, rated: 0 };
    }
    if (sim.mode === "run") sim.hour.rated += dt * product().ratePerHour / 3600;
}
function hourSummary() {
    if (!sim.hour) return null;
    const good = outputMachine().count_good - sim.hour.good0, rated = Math.round(sim.hour.rated);
    return { start: sim.hour.start, good, rated, pct: rated > 0 ? Math.round(good / rated * 1000) / 10 : null };
}

function applyPreset(name) {
    const pr = name === "line" ? {} : (sim.line.presets || {})[name];
    if (!pr) { node.warn("unknown preset " + name); return; }
    const f = (k) => (pr[k] != null ? pr[k] : 1);
    for (const m of sim.machines) {
        const b = sim.base.machines.find(x => x.slot === m.cfg.slot);
        m.cfg.mtbfH = b.mtbfH * f("mtbf");
        m.cfg.mttrMin = b.mttrMin * f("mttr");
        m.cfg.jamsPerH = b.jamsPerH * f("jams");
        m.cfg.rejectPct = b.rejectPct * f("rejects");
        m.cfg.speedPct = m.cfg.constraint && pr.constraintSpeedPct != null ? pr.constraintSpeedPct : b.speedPct;
        if (b.shortage) m.cfg.shortage.perShift = b.shortage.perShift * f("shortages");
    }
    sim.line.quality.weightSigmaPct = sim.base.quality.weightSigmaPct * f("weightSpread");
    sim.preset = name;
}

const product = () => sim.line.products.find(p => p.sku === sim.sku) || sim.line.products[0];

function setpointOf(m) {
    const c = m.cfg;
    const rated = c.constraint ? Math.min(c.ratedPerMin, product().ratePerHour / 60) : c.ratedPerMin;
    return rated * c.speedPct / 100;
}

// Expected time between two units leaving machine j when the line runs at
// the constraint's pace: one carton every 0.6 s at 100/min, but one case only
// every 6 s after the case packer. Waiting that long is normal, not starved.
function paceMs(j) {
    const k = sim.machines.findIndex(x => x.cfg.constraint);
    let rate = Math.max(setpointOf(sim.machines[k]), 0.1);
    for (let x = k + 1; x <= j; x++) rate /= Math.max(sim.machines[x].cfg.inPerUnit, 1);
    return Math.min(60000 / rate, 60000);
}

function startFault(m, kind) {
    const c = m.cfg;
    if (kind === "breakdown") {
        const unknown = rand() < (sim.line.unknownFaultPct || 0) / 100;
        const code = unknown || !(c.breakdowns || []).length ? 999 : pick(c.breakdowns);
        m.fault = { code, left: c.mttrMin * 60 * Math.exp(0.5 * normal()), kind };   // log-normal around MTTR
    } else if (kind === "jam") {
        m.fault = { code: c.jam || 999, left: uniform(10, 90), kind };
    } else if (kind === "shortage") {
        m.fault = { code: c.shortage.code, left: uniform(c.shortage.minMin, c.shortage.maxMin) * 60, kind };
    }
}

// --- one machine, one tick ---------------------------------------------------------------
function step(i, dt) {
    const m = sim.machines[i], c = m.cfg;
    const up = i > 0 ? sim.machines[i - 1] : null;          // its conveyor feeds this machine
    const last = i === sim.machines.length - 1;
    m.setpoint = setpointOf(m);
    if (m.fault && !m.fault.hold) {                          // repairs go on in every mode
        m.fault.left -= dt;
        if (m.fault.left <= 0) m.fault = null;
    }
    // A stopped machine makes nothing. When the whole line is stopped, the
    // clocks for starved and blocked restart, so the next start is not
    // reported as starved before the first carton could arrive.
    const halt = (st, lineStopped) => {
        m.state = st; m.acc = 0; m.speedEma = 0; m.waiting = null;
        if (lineStopped) m.lastOutAt = m.lastTakenAt = now;
    };
    if (m.fault) return halt(STATE.fault, sim.mode !== "run");
    if (sim.mode !== "run") return halt(MODE_STATE[sim.mode], true);

    if (m.state === STATE.running) {                         // only a running machine wears out or jams
        if (c.mtbfH > 0 && rand() < dt / (c.mtbfH * 3600)) startFault(m, "breakdown");
        else if (c.jamsPerH > 0 && rand() < dt * c.jamsPerH / 3600) startFault(m, "jam");
        else if (c.shortage && c.shortage.perShift > 0 && rand() < dt * c.shortage.perShift / (8 * 3600)) startFault(m, "shortage");
        if (m.fault) return halt(STATE.fault);
    }

    const wasRunning = m.state;
    m.acc += m.setpoint * dt / 60;                       // progress of the unit in hand
    let made = 0, starved = false, blocked = false;
    while (m.acc >= 1) {
        if (c.inPerUnit > 0 && up.buffer < c.inPerUnit) { starved = true; break; }
        if (!last && m.buffer >= c.bufferAfter) { blocked = true; break; }
        if (c.inPerUnit > 0) { up.buffer -= c.inPerUnit; up.lastTakenAt = now; }
        m.acc -= 1;
        made++;
        m.count_in++;
        let bad;
        if (c.weigher) {                                     // the filler's count accuracy shows up here
            const p = product(), q = sim.line.quality;
            const w = p.targetWeightG * (1 + normal() * q.weightSigmaPct / 100);
            const dev = (w / p.targetWeightG - 1) * 100;
            m.process_value = round1(w);
            bad = dev < q.rejectBelowPct || dev > q.rejectAbovePct;
        } else {
            bad = c.rejectPct > 0 && rand() < c.rejectPct / 100;
        }
        if (bad) { m.count_reject++; continue; }
        m.count_good++;
        if (!last) { m.buffer++; m.lastOutAt = now; continue; }
        if (++m.casesOnPallet >= (sim.line.palletCases || 60)) {   // last machine: a pallet is full
            m.casesOnPallet = 0;
            m.process_value = ++m.pallets;
            const w = c.palletWait;
            if (w && rand() < w.probability) {
                m.fault = { code: w.code, left: uniform(w.minMin, w.maxMin) * 60, kind: "pallet" };
                return halt(STATE.fault);
            }
        }
    }
    // Starved: waiting for input while the machine before it has delivered
    // nothing for debounceS plus 1.5 of its normal intervals (paceMs).
    // Blocked: waiting for space while the machine after it has taken nothing
    // for as long. A faster machine that waits a moment
    // for the next carton, or a case packer collecting a set of 10, is running.
    if (starved || blocked) m.acc = Math.min(m.acc, 1);  // a waiting machine holds one finished cycle, no more
    if (made > 0) m.waiting = null;
    if (starved) m.waiting = "in";
    if (blocked) m.waiting = "out";
    const debounce = (sim.line.debounceS || 2) * 1000;
    if (m.waiting === "in" && now - up.lastOutAt >= debounce + 1.5 * paceMs(i - 1)) m.state = STATE.starved;
    else if (m.waiting === "out" && now - m.lastTakenAt >= debounce + 1.5 * paceMs(i + 1)) m.state = STATE.blocked;
    else m.state = STATE.running;
    // Shown speed: units actually made per minute, averaged over about 20 s;
    // a machine that starts running starts at the line's pace (or its own
    // set speed, if lower).
    if (m.state !== STATE.running) m.speedEma = 0;
    else {
        if (wasRunning !== STATE.running) m.speedEma = Math.min(m.setpoint, 60000 / paceMs(i));   // starts at the line's pace
        m.speedEma += (made * 60 / dt - m.speedEma) * (1 - Math.exp(-dt / 20));
        m.speedEma = Math.min(m.speedEma, m.setpoint);
    }
}

// --- work orders (step 3a.5) --------------------------------------------------------------
function orderDone() {
    const o = sim.order;
    return o.active && outputMachine().count_good - o.goodAtStart >= o.plannedQty;
}
function receiveOrder(topic, payload) {
    const cfg = sim.line.orders || {};
    if (!cfg.ofmLine || topic !== cfg.ofmLine + "/workorder") return;
    let p = payload;
    if (typeof p === "string") { try { p = p ? JSON.parse(p) : null; } catch (e) { p = null; } }
    if (!p || p.active !== true) { sim.order = { active: false, ts: p && p.ts }; return; }
    const same = sim.order.active && sim.order.workOrderId === p.workOrderId;
    sim.order = Object.assign({}, p, { goodAtStart: same ? sim.order.goodAtStart : outputMachine().count_good });
    sim.auto.pending = null;
    // The operator pressed "Changeover done" in OFM (line view): the crew has
    // finished, so the line starts now. (OFM's own end of the changeover, at
    // the first good carton, comes after the setup anyway.)
    if (same && sim.follow && p.changeover === false && now < sim.changeoverUntil) sim.changeoverUntil = now;
    if (same || !sim.follow) return;
    // A new order: a new product means a changeover (same product: none).
    const prod = sim.line.products.find(x => x.sku === p.sku);
    if (!prod) { node.warn("work order " + p.woNumber + ": product " + p.sku + " is not in line.json; the line keeps " + sim.sku); return; }
    if (prod.sku !== sim.sku) {
        sim.sku = prod.sku;
        sim.changeoverUntil = now + prod.changeoverMin * uniform(0.8, 1.2) * 60000;
    }
}
// The auto-operator: start the plan's next order when the line has nothing
// to do inside the shift pattern, after a realistic pause.
function autoOperator(scheduled) {
    const a = sim.auto, cfg = (sim.line.orders || {}).autoOperator || {};
    const plan = cfg.plan || [];
    if (!a.enabled || !sim.follow || !plan.length || sim.stopped || !scheduled) { a.waitingSince = null; return null; }
    if (sim.order.active && !orderDone()) { a.waitingSince = null; return null; }
    if (a.pending && now - a.pending < 60000) return null;       // asked, no answer yet
    if (a.waitingSince === null) a.waitingSince = now;
    if (now - a.waitingSince < (Number(cfg.delayMin) >= 0 ? Number(cfg.delayMin) : 2) * 60000) return null;
    const next = plan[a.next % plan.length];
    a.next = (a.next + 1) % plan.length;
    a.pending = now;
    a.waitingSince = null;
    return { topic: "order", payload: { cmd: "start", sku: next.sku, qty: next.qty, by: "auto-operator" } };
}

function panel() {
    const s = snapshot();
    const sch = sim.line.schedule || {};
    return Object.assign(s, {
        line: sim.line.line, paused: sim.paused, preset: sim.preset,
        schedule: { enabled: !!sch.enabled, days: sch.days, start: sch.start, end: sch.end, cleaning: sch.cleaning },
        localTime: new Date(now).toLocaleString("en-AU", { timeZone: sch.timeZone || "Australia/Melbourne", weekday: "short", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }),
        products: sim.line.products.map(p => ({ sku: p.sku, description: p.description, ratePerHour: p.ratePerHour, changeoverMin: p.changeoverMin })),
        presets: [{ name: "line", label: "As in line.json" }].concat(Object.entries(sim.line.presets || {}).map(([name, p]) => ({ name, label: p.label || name }))),
        changeoverLeftS: now < sim.changeoverUntil ? Math.round((sim.changeoverUntil - now) / 1000) : 0,
        hour: hourSummary(), lastHour: sim.lastHour, lineOutput: outputMachine().cfg.name,
        order: Object.assign({}, sim.order, sim.order.active ? { made: outputMachine().count_good - sim.order.goodAtStart, done: orderDone() } : {}),
        follow: sim.follow, ofmLine: (sim.line.orders || {}).ofmLine || null,
        auto: { enabled: sim.auto.enabled, pending: !!sim.auto.pending, lastError: sim.auto.lastError,
                startsInS: sim.auto.waitingSince !== null ? Math.max(0, Math.round(((Number(((sim.line.orders || {}).autoOperator || {}).delayMin) || 0) * 60000 - (now - sim.auto.waitingSince)) / 1000)) : null,
                next: (((sim.line.orders || {}).autoOperator || {}).plan || [])[sim.auto.next] || null },
        machines: s.machines.map((x, i) => {
            const m = sim.machines[i], c = m.cfg;
            return Object.assign(x, {
                display: c.display || c.name, unit: c.unit || "unit", constraint: !!c.constraint,
                faultKind: m.fault ? m.fault.kind : null, faultLeftS: m.fault && !m.fault.hold ? Math.round(m.fault.left) : null,
                settings: { speedPct: c.speedPct, mtbfH: round1(c.mtbfH), mttrMin: round1(c.mttrMin), jamsPerH: round1(c.jamsPerH), rejectPct: Math.round(c.rejectPct * 100) / 100 }
            });
        })
    });
}
// The panel is fed once a second, whatever else happens.
function panelDue() {
    if (now - sim.lastPanel < 1000) return null;
    sim.lastPanel = now;
    return { topic: "panel", payload: panel() };
}

function snapshot() {
    return {
        ts: now, mode: sim.mode, sku: sim.sku, stopped: sim.stopped, heartbeat: sim.heartbeat,
        machines: sim.machines.map(m => ({
            slot: m.cfg.slot, name: m.cfg.name,
            state: m.state, fault_code: m.fault ? m.fault.code : 0,
            count_in: m.count_in, count_good: m.count_good, count_reject: m.count_reject,
            speed: round1(m.speedEma), speed_setpoint: round1(m.setpoint),
            heartbeat: sim.heartbeat, process_value: m.process_value,
            buffer: m.buffer, buffer_capacity: m.cfg.bufferAfter || 0
        }))
    };
}

// --- messages ------------------------------------------------------------------------------
if (msg.topic === "config") {
    sim = build(msg.payload, sim);
    context.set("sim", sim);
    return null;
}
if (!sim) return null;

if (typeof msg.topic === "string" && msg.topic.endsWith("/workorder")) {
    receiveOrder(msg.topic, msg.payload);
    sim.lastPanel = 0;
    return null;
}
if (msg.topic === "orderresult") {
    sim.auto.pending = null;
    sim.auto.lastError = msg.ok ? null : msg.error;
    sim.lastPanel = 0;
    return null;
}

if (msg.topic === "cmd") {
    const p = msg.payload || {};
    const m = sim.machines.find(x => x.cfg.slot === p.slot);
    switch (p.cmd) {
        case "break":
            if (m) m.fault = { code: p.code || (m.cfg.breakdowns || [])[0] || 999,
                               left: (p.minutes != null ? p.minutes : m.cfg.mttrMin) * 60, kind: "manual", hold: p.hold === true };
            break;
        case "jam":     if (m) m.fault = { code: m.cfg.jam || 999, left: p.seconds != null ? p.seconds : 30, kind: "jam" }; break;
        case "repair":  if (m) m.fault = null; break;
        case "stop":    sim.stopped = true; break;
        case "run":     sim.stopped = false; break;
        case "pause":   sim.paused = true; break;
        case "resume":  sim.paused = false; sim.last = now; break;
        case "product": {
            const prod = sim.line.products.find(x => x.sku === p.sku);
            if (!prod) { node.warn("unknown product " + p.sku); break; }
            sim.sku = prod.sku;
            // A changeover lasts the given minutes exactly (control panel), or
            // the product's changeoverMin from line.json give or take 20 %.
            if (p.changeover !== false) {
                const minutes = Number.isFinite(p.minutes) && p.minutes >= 0 ? p.minutes : prod.changeoverMin * uniform(0.8, 1.2);
                sim.changeoverUntil = now + minutes * 60000;
            }
            break;
        }
        case "schedule": sim.line.schedule.enabled = p.enabled === true; sim.scheduleCache = { minute: -1, mode: null }; break;
        case "preset":  applyPreset(p.name); break;
        case "newrun":                                           // a fresh run: product and settings stay
            for (const x of sim.machines) {
                Object.assign(x, { count_in: 0, count_good: 0, count_reject: 0, process_value: 0, pallets: 0, casesOnPallet: 0,
                                   buffer: 0, fault: null, acc: 0, waiting: null, speedEma: 0, lastOutAt: now, lastTakenAt: now });
            }
            Object.assign(sim, { changeoverUntil: 0, stopped: false, paused: false, last: now, hour: null, lastHour: null });
            if (sim.order.active) sim.order.goodAtStart = 0;
            break;
        case "follow":  sim.follow = p.enabled === true; break;
        case "auto":    sim.auto.enabled = p.enabled === true; sim.auto.waitingSince = null; sim.auto.lastError = null; break;
        case "startorder":
        case "completeorder": {
            sim.lastPanel = 0;
            const req = p.cmd === "startorder" ? { cmd: "start", sku: p.sku, qty: p.qty, by: "simulator panel" } : { cmd: "complete", by: "simulator panel" };
            return [null, null, { topic: "order", payload: req }];
        }
        case "set":
            if (m && MACHINE_KEYS.includes(p.key) && Number.isFinite(p.value) && p.value >= 0) { m.cfg[p.key] = p.value; sim.preset = "custom"; }
            else if (!m && LINE_KEYS.includes(p.key) && Number.isFinite(p.value)) sim.line[p.key] = p.value;
            else node.warn("cannot set " + p.key);
            break;
        default: node.warn("unknown command " + p.cmd);
    }
    sim.lastPanel = 0;                                           // show the effect at once
    return null;
}

// tick
if (sim.paused) {
    node.status({ fill: "grey", shape: "ring", text: "paused - values frozen, heartbeat stopped" });
    sim.last = now;
    return [null, panelDue(), null];
}
let dt = (now - sim.last) / 1000;
sim.last = now;
if (dt <= 0) return null;
dt = Math.min(dt, 1);                                        // after a hold-up, never jump ahead

let mode = sim.stopped ? "off" : scheduleMode(now);
const scheduled = mode === "run" || mode === "setup";
if (mode === "run" && now < sim.changeoverUntil) mode = "setup";
if (mode === "run" && sim.follow && (!sim.order.active || orderDone())) mode = "waiting";
sim.mode = mode;
for (let i = sim.machines.length - 1; i >= 0; i--) step(i, dt);   // downstream first: space frees before upstream pushes
trackHour(dt);

const second = Math.floor(now / 1000);
if (second !== sim.lastSecond) {
    sim.lastSecond = second;
    sim.heartbeat++;
    const k = sim.machines.find(x => x.cfg.constraint);
    node.status({ fill: mode === "run" ? "green" : "yellow", shape: "dot",
                  text: mode + " · " + sim.sku + " · " + k.cfg.name + " " + Object.keys(STATE).find(s => STATE[s] === k.state) +
                        " " + round1(k.speedEma) + "/min · good " + k.count_good });
}
return [{ topic: "snapshot", payload: snapshot() }, panelDue(), autoOperator(scheduled)];

// Simulated OPC UA PLCs (ADR-0023): one OPC UA server per machine, so each
// machine looks like its own PLC to OFM. Machine in slot n is
// opc.tcp://linesim:484n, namespace urn:ofm:linesim:m<n>, nodes s=State,
// s=FaultCode, s=CountIn, s=CountGood, s=CountReject, s=Speed,
// s=SpeedSetpoint, s=Heartbeat, s=ProcessValue (demo README, section 5).
// Values carry the simulator's own time as source timestamp (tss: device).
// REAL signals are Double here (a PLC REAL is 32-bit, so 96.2 would arrive
// as 96.19999694824219); integers have the PLC's sizes (INT 16, DINT 32 bit).
// Input: the line engine's snapshot. Output: none.
const opcua = global.get("opcua");
const SIGNALS = [
    ["state", "State", "Int16"], ["fault_code", "FaultCode", "Int16"],
    ["count_in", "CountIn", "Int32"], ["count_good", "CountGood", "Int32"], ["count_reject", "CountReject", "Int32"],
    ["speed", "Speed", "Double"], ["speed_setpoint", "SpeedSetpoint", "Double"],
    ["heartbeat", "Heartbeat", "Int32"], ["process_value", "ProcessValue", "Double"]
];
const servers = context.get("servers") || {};
context.set("servers", servers);

async function start(machine, s) {
    const slot = machine.slot, uri = "urn:ofm:linesim:m" + slot;
    try {
        const pki = (env.get("OFM_LINESIM_PKI_DIR") || "/data/linesim-pki") + "/m" + slot;
        const server = new opcua.OPCUAServer({
            port: 4840 + slot,
            resourcePath: "",
            alternateHostname: "localhost",                           // also offered as opc.tcp://localhost:484n, for a desktop client
            buildInfo: { productName: "OFM simulated PLC m" + slot, buildNumber: "1", buildDate: new Date() },
            serverInfo: { applicationUri: uri, productUri: "urn:ofm:linesim",
                          applicationName: { text: "OFM linesim " + machine.name, locale: "en" } },
            serverCertificateManager: new opcua.OPCUACertificateManager({
                rootFolder: pki, automaticallyAcceptUnknownCertificate: true }),
            securityModes: [opcua.MessageSecurityMode.None],           // a simulator: no encryption, no login
            securityPolicies: [opcua.SecurityPolicy.None],
            allowAnonymous: true
        });
        s.server = server;
        await server.initialize();
        const space = server.engine.addressSpace;
        const ns = space.registerNamespace(uri);
        const folder = ns.addObject({ organizedBy: space.rootFolder.objects, browseName: machine.name });
        s.vars = {};
        for (const [key, browse, type] of SIGNALS) {
            s.vars[key] = ns.addVariable({
                componentOf: folder, browseName: browse, nodeId: "s=" + browse,
                dataType: type, minimumSamplingInterval: 100,
                value: new opcua.Variant({ dataType: opcua.DataType[type], value: 0 })
            });
        }
        await server.start();
        s.state = "up";
        s.endpoint = "opc.tcp://linesim:" + (4840 + slot);
    } catch (e) {
        s.state = "failed";
        s.error = (e && (e.message || String(e))) || "unknown error";
        node.error("OPC UA server for slot " + slot + " (" + machine.name + "): " + s.error + (e && e.stack ? "\n" + e.stack : ""));
    }
}

const snap = msg.payload;
for (const machine of snap.machines) {
    let s = servers[machine.slot];
    if (!s) {
        s = servers[machine.slot] = { state: "starting", last: {} };
        start(machine, s);                                       // runs in the background
        continue;
    }
    if (s.state !== "up") continue;
    const ts = new Date(snap.ts);
    for (const [key, , type] of SIGNALS) {
        const v = machine[key];
        if (s.last[key] === v) continue;                         // send changes only
        s.last[key] = v;
        s.vars[key].setValueFromSource(new opcua.Variant({ dataType: opcua.DataType[type], value: v }),
                                       opcua.StatusCodes.Good, ts);
    }
}
const list = Object.values(servers);
const up = list.filter(s => s.state === "up").length, failed = list.filter(s => s.state === "failed").length;
if (context.get("shown") !== up + "/" + failed) {
    context.set("shown", up + "/" + failed);
    node.status(failed ? { fill: "red", shape: "ring", text: failed + " failed, " + up + " up (see log)" }
                       : { fill: up === list.length ? "green" : "yellow", shape: "dot", text: up + " of " + list.length + " OPC UA servers up, ports 4841-484" + list.length });
}
return null;

finalize:
// On Stop (redeploy, restart): close every OPC UA server, so the ports are free again.
const servers = context.get("servers") || {};
const closing = Object.values(servers).filter(s => s.server).map(s => s.server.shutdown(0).catch(() => {}));
context.set("servers", {});
return Promise.all(closing);

