// Control panel -> line engine. Passes on known commands only, with their
// numbers checked, and shows the last one under this node.
const ALLOWED = ["break", "jam", "repair", "stop", "run", "pause", "resume", "product", "schedule", "set", "preset", "newrun",
                 "follow", "auto", "startorder", "completeorder"];
const p = msg.payload || {};
if (!ALLOWED.includes(p.cmd)) {
    node.warn("ignored: " + JSON.stringify(p));
    return null;
}
if (p.cmd === "set") {
    p.value = Number(p.value);
    if (!Number.isFinite(p.value) || p.value < 0) {
        node.warn("ignored: " + p.key + " must be a number, 0 or more");
        return null;
    }
}
if (p.cmd === "product" && p.minutes != null) {
    p.minutes = Number(p.minutes);
    if (!Number.isFinite(p.minutes) || p.minutes < 0) {
        node.warn("ignored: changeover minutes must be a number, 0 or more");
        return null;
    }
}
if (p.cmd === "startorder") {
    p.qty = Math.round(Number(p.qty));
    if (!p.sku || !(p.qty > 0)) {
        node.warn("ignored: an order needs a product and a quantity above 0");
        return null;
    }
}
node.status({ fill: "blue", shape: "dot",
              text: p.cmd + (p.slot ? " slot " + p.slot : "") + (p.key ? " " + p.key + "=" + p.value : "") +
                    (p.sku ? " " + p.sku : "") + (p.name ? " " + p.name : "") + " · " + new Date().toLocaleTimeString() });
return { topic: "cmd", payload: p };

// Connect to OFM's UNS as the read-only user and listen to the demo line's
// work order (step 3a.5): {orders.ofmLine}/workorder from line.json.
// Input: the line from "load line.json". Output: control messages for the
// MQTT node (connect, then unsubscribe the old topic and subscribe the new).
// The password comes from deploy/.env, so nothing secret is in the flow file.
const line = msg.payload || {};
const topic = line.orders && line.orders.ofmLine ? line.orders.ofmLine + "/workorder" : null;
const out = [];
if (!context.get("connected")) {
    out.push({ action: "connect", broker: {
        broker: "mosquitto", port: 1883, clientid: "ofm-linesim",
        username: "ofm_reader", password: env.get("OFM_MQTT_READER_PASSWORD")
    } });
    context.set("connected", true);
}
const old = context.get("topic");
if (old && old !== topic) out.push({ action: "unsubscribe", topic: old });
if (topic && topic !== old) out.push({ action: "subscribe", topic, qos: 1 });
context.set("topic", topic);
node.status(topic ? { fill: "green", shape: "dot", text: "following " + topic } : { fill: "grey", shape: "ring", text: "no orders.ofmLine in line.json" });
return [out];

// Work orders, the simulator's side (step 3a.5, ADR-0023 decision 6).
// Input: from the line engine, msg.payload = start {sku, qty, by} or
// complete {by}. Calls OFM's database as the role ofm_demo, which may only
// call the functions of schema demo (db/examples/demo-packline.sql):
// demo.start_order creates and starts an order on the demo line (completing
// the running one), demo.complete_order completes the running one. OFM then
// publishes the new order on .../workorder, and the engine follows that.
// Output: "orderresult" {ok, error} back to the engine (shown in the panel).
const pg = global.get("pg");
const p = msg.payload || {};
const result = (ok, error) => ({ topic: "orderresult", ok, error: error || null });
const password = env.get("OFM_DEMO_DB_PASSWORD");
if (!pg) return result(false, "the pg library is not available");
if (!password) {
    node.status({ fill: "red", shape: "ring", text: "OFM_DEMO_DB_PASSWORD not set" });
    return result(false, "OFM_DEMO_DB_PASSWORD is not set in .env: run make-env.sh, then docker compose up -d");
}
const db = new pg.Client({
    host: "timescaledb", port: 5432, database: "ofm", user: "ofm_demo", password,
    application_name: "ofm-linesim", connectionTimeoutMillis: 5000
});
try {
    await db.connect();
    if (p.cmd === "start") {
        const qty = Math.round(Number(p.qty));
        if (!p.sku || !(qty > 0)) throw new Error("a product and a quantity above 0 are needed");
        const r = await db.query("SELECT demo.start_order($1, $2, $3) AS id", [p.sku, qty, p.by || "simulator"]);
        node.status({ fill: "green", shape: "dot", text: "started " + p.sku + " × " + qty + " (order " + r.rows[0].id + ") · " + new Date().toLocaleTimeString() });
    } else if (p.cmd === "complete") {
        const r = await db.query("SELECT demo.complete_order($1) AS id", [p.by || "simulator"]);
        node.status({ fill: "green", shape: "dot", text: (r.rows[0].id ? "completed order " + r.rows[0].id : "no active order") + " · " + new Date().toLocaleTimeString() });
    } else {
        throw new Error("unknown request " + p.cmd);
    }
    return result(true);
} catch (e) {
    const text = e.code === "28P01" ? "the database refused ofm_demo's password: run migrate demo again after setting OFM_DEMO_DB_PASSWORD"
               : e.code === "3F000" || e.code === "42883" ? "the demo is not loaded in OFM: docker compose run --rm migrate demo"
               : e.message;
    node.status({ fill: "red", shape: "ring", text: text });
    node.warn("work order " + p.cmd + ": " + text);
    return result(false, text);
} finally {
    db.end().catch(() => { /* already closed */ });
}
